/**
 * The Hill Conduit — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { HILL_CONDUIT_TEMPLATE } from '../hill-conduit';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Hill Conduit — template structure", () => {
  it('carries its identity', () => {
    expect(HILL_CONDUIT_TEMPLATE.id).toBe('encounter.town.hill_conduit');
    expect(HILL_CONDUIT_TEMPLATE.reach).toBe('stone');
    expect(HILL_CONDUIT_TEMPLATE.rarityTier).toBe(2);
    expect(HILL_CONDUIT_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = HILL_CONDUIT_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['conduit.show_the_straight_course', 'conduit.mark_the_boundary']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['mind', 'order']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(HILL_CONDUIT_TEMPLATE.settings).toEqual(['rural', 'urban']);
    expect(HILL_CONDUIT_TEMPLATE.locationSubtypes).toEqual(expandSettings(['rural', 'urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(HILL_CONDUIT_TEMPLATE.consequenceDraw).toEqual(['condition', 'drive']);
    expect(HILL_CONDUIT_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.hill_conduit',
          reach: 'stone',
          rarityTier: 2,
        }),
        HILL_CONDUIT_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
